-- Acht synthetische belegte Callerziele mit je genau einer Schemaabweichung.
-- Nur KeepData=1-Abweisung; kein Schemaumbau oder allgemeiner Catalogvertrag.
SET NOCOUNT ON;
IF @@TRANCOUNT<>0 OR XACT_STATE()<>0 THROW 55396,N'CSV schema preservation: neutraler Start fehlt.',1;
CREATE TABLE #CsvSchemaProgress(Id int NOT NULL PRIMARY KEY CHECK(Id BETWEEN 1 AND 8));
CREATE TABLE #CsvSchemaSource(RowKind varchar(6) COLLATE Latin1_General_100_BIN2 NOT NULL,RowOrdinal bigint NOT NULL,ColumnOrdinal int NOT NULL,[Value] nvarchar(max) COLLATE Latin1_General_100_BIN2 NULL,PRIMARY KEY(RowOrdinal,ColumnOrdinal));
INSERT #CsvSchemaSource VALUES('DATA',1,1,REPLICATE(CONVERT(nvarchar(max),N'w'),8388606));
-- Fall 1: Parser, Abweichung Spaltenname.
CREATE TABLE #CsvSchema1(RowKind varchar(6) COLLATE Latin1_General_100_BIN2 NOT NULL,RowOrdinal bigint NOT NULL,ColumnOrdinal int NOT NULL,[Payload] nvarchar(max) COLLATE Latin1_General_100_BIN2 NULL,PRIMARY KEY(RowOrdinal,ColumnOrdinal));
DECLARE @Old nvarchar(max)=REPLICATE(CONVERT(nvarchar(max),N'p'),8388608),@Source nvarchar(max)=REPLICATE(CONVERT(nvarchar(max),N'w'),8388606),@Text nvarchar(max)=REPLICATE(CONVERT(nvarchar(max),N'x'),8388608),@Caught bit=0,@TargetId int=OBJECT_ID(N'tempdb..#CsvSchema1'),@SourceId int=OBJECT_ID(N'tempdb..#CsvSchemaSource');
INSERT #CsvSchema1 VALUES('DATA',99,99,@Old);
IF DATALENGTH(@Old)<>16777216 OR DATALENGTH(@Text)<>16777216 OR DATALENGTH(@Source+NCHAR(13)+NCHAR(10))<>16777216 THROW 55396,N'CSV schema preservation: Fixturebytes weichen ab.',2;
IF (SELECT COUNT_BIG(*) FROM #CsvSchema1)<>1 OR NOT EXISTS(SELECT 1 FROM #CsvSchema1 WHERE DATALENGTH(RowKind)=4 AND CONVERT(varbinary(max),RowKind)=0x44415441 AND RowOrdinal=99 AND ColumnOrdinal=99 AND [Payload] IS NOT NULL AND DATALENGTH([Payload])=16777216 AND CONVERT(varbinary(max),[Payload])=CONVERT(varbinary(max),@Old)) OR (SELECT COUNT_BIG(*) FROM #CsvSchemaSource)<>1 OR NOT EXISTS(SELECT 1 FROM #CsvSchemaSource WHERE DATALENGTH(RowKind)=4 AND CONVERT(varbinary(max),RowKind)=0x44415441 AND RowOrdinal=1 AND ColumnOrdinal=1 AND [Value] IS NOT NULL AND DATALENGTH([Value])=DATALENGTH(@Source) AND CONVERT(varbinary(max),[Value])=CONVERT(varbinary(max),@Source)) THROW 55396,N'CSV schema preservation: volle Baseline weicht ab.',3;
SELECT * INTO #CsvSchemaColumns FROM(SELECT column_id,CONVERT(varbinary(256),name) AS ColumnName,system_type_id,user_type_id,max_length,precision,scale,is_nullable,CONVERT(varbinary(256),collation_name) AS CollationName,is_identity,is_computed FROM tempdb.sys.columns WHERE object_id=@TargetId) snapshot;
SELECT * INTO #CsvSchemaIndexes FROM(SELECT index_id,CONVERT(varbinary(256),name) AS IndexName,type,is_unique,is_primary_key,is_unique_constraint,has_filter,filter_definition FROM tempdb.sys.indexes WHERE object_id=@TargetId) snapshot;
SELECT * INTO #CsvSchemaKeys FROM(SELECT index_id,index_column_id,column_id,key_ordinal,is_descending_key,is_included_column FROM tempdb.sys.index_columns WHERE object_id=@TargetId) snapshot;
BEGIN TRY EXEC toolbelt_file.USP_ParseCsv @Text=@Text,@KeepData=1,@ResultTable=N'#CsvSchema1'; END TRY
BEGIN CATCH IF ERROR_NUMBER()<>51025 OR ERROR_STATE()<>1 THROW; SET @Caught=1; END CATCH;
IF @Caught<>1 THROW 55396,N'CSV schema preservation: exakte Schemaabweisung fehlt.',4;
IF @@TRANCOUNT<>0 OR XACT_STATE()<>0 THROW 55396,N'CSV schema preservation: Transaktionsneutralitaet fehlt.',5;
IF OBJECT_ID(N'tempdb..#CsvSchema1')<>@TargetId OR OBJECT_ID(N'tempdb..#CsvSchemaSource')<>@SourceId THROW 55396,N'CSV schema preservation: Calleridentitaet weicht ab.',6;
IF (SELECT COUNT_BIG(*) FROM #CsvSchema1)<>1 OR NOT EXISTS(SELECT 1 FROM #CsvSchema1 WHERE DATALENGTH(RowKind)=4 AND CONVERT(varbinary(max),RowKind)=0x44415441 AND RowOrdinal=99 AND ColumnOrdinal=99 AND [Payload] IS NOT NULL AND DATALENGTH([Payload])=16777216 AND CONVERT(varbinary(max),[Payload])=CONVERT(varbinary(max),@Old)) OR (SELECT COUNT_BIG(*) FROM #CsvSchemaSource)<>1 OR NOT EXISTS(SELECT 1 FROM #CsvSchemaSource WHERE DATALENGTH(RowKind)=4 AND CONVERT(varbinary(max),RowKind)=0x44415441 AND RowOrdinal=1 AND ColumnOrdinal=1 AND [Value] IS NOT NULL AND DATALENGTH([Value])=DATALENGTH(@Source) AND CONVERT(varbinary(max),[Value])=CONVERT(varbinary(max),@Source)) THROW 55396,N'CSV schema preservation: voller Ziel- oder Quellerhalt fehlt.',7;
IF EXISTS(SELECT * FROM #CsvSchemaColumns EXCEPT SELECT column_id,CONVERT(varbinary(256),name) AS ColumnName,system_type_id,user_type_id,max_length,precision,scale,is_nullable,CONVERT(varbinary(256),collation_name) AS CollationName,is_identity,is_computed FROM tempdb.sys.columns WHERE object_id=@TargetId) OR EXISTS(SELECT column_id,CONVERT(varbinary(256),name) AS ColumnName,system_type_id,user_type_id,max_length,precision,scale,is_nullable,CONVERT(varbinary(256),collation_name) AS CollationName,is_identity,is_computed FROM tempdb.sys.columns WHERE object_id=@TargetId EXCEPT SELECT * FROM #CsvSchemaColumns) THROW 55396,N'CSV schema preservation: Columns-Snapshot driftet.',8;
DROP TABLE #CsvSchemaColumns;
IF EXISTS(SELECT * FROM #CsvSchemaIndexes EXCEPT SELECT index_id,CONVERT(varbinary(256),name) AS IndexName,type,is_unique,is_primary_key,is_unique_constraint,has_filter,filter_definition FROM tempdb.sys.indexes WHERE object_id=@TargetId) OR EXISTS(SELECT index_id,CONVERT(varbinary(256),name) AS IndexName,type,is_unique,is_primary_key,is_unique_constraint,has_filter,filter_definition FROM tempdb.sys.indexes WHERE object_id=@TargetId EXCEPT SELECT * FROM #CsvSchemaIndexes) THROW 55396,N'CSV schema preservation: Indexes-Snapshot driftet.',8;
DROP TABLE #CsvSchemaIndexes;
IF EXISTS(SELECT * FROM #CsvSchemaKeys EXCEPT SELECT index_id,index_column_id,column_id,key_ordinal,is_descending_key,is_included_column FROM tempdb.sys.index_columns WHERE object_id=@TargetId) OR EXISTS(SELECT index_id,index_column_id,column_id,key_ordinal,is_descending_key,is_included_column FROM tempdb.sys.index_columns WHERE object_id=@TargetId EXCEPT SELECT * FROM #CsvSchemaKeys) THROW 55396,N'CSV schema preservation: Keys-Snapshot driftet.',8;
DROP TABLE #CsvSchemaKeys;
DROP TABLE #CsvSchema1;
INSERT #CsvSchemaProgress VALUES(1);

GO
